<script setup lang="ts">
import { onMounted,onUnmounted,ref } from 'vue'
import { ElButton,ElSelect,ElOption,ElInput,ElTag,ElDialog,ElCheckbox,ElAlert } from 'element-plus'
import { API } from '../../../shared/api'
import { dateLabel,isCancelled } from '../../../shared/console'
const props=defineProps<{api:API}>();const emit=defineEmits<{changed:[];open:[page:string]}>()
const rows=ref<any[]>([]),status=ref('pending'),selected=ref<any>(null),source=ref<any>(null),error=ref(''),busy=ref(false),confirm=ref(false),checked=ref(false),action=ref('approve')
const linkClaim=ref(false),predicate=ref('residence'),value=ref(''),scope=ref('{}')
const slots=['residence','occupation','school','response_language','response_detail','diet','work_habit','hobby','learning_goal','project_goal','time_preference','budget']
let alive=true
async function load(){busy.value=true;try{rows.value=await props.api.request('/memory-reviews?limit=500&status='+status.value,undefined,'GET','review-list')}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}finally{if(alive)busy.value=false}}
async function inspect(item:any){selected.value={...item};source.value=null;checked.value=false;linkClaim.value=false;value.value='';scope.value='{}';try{const result=await props.api.request('/claim-source/'+encodeURIComponent(item.source_ref),undefined,'GET','review-source');if(alive&&selected.value?.id===item.id)source.value=result}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}}
function propose(kind:string){action.value=kind;checked.value=false;confirm.value=true}
async function apply(){if(!checked.value||!selected.value)return;busy.value=true;try{const item=selected.value;if(action.value==='approve'&&!source.value?.personal_claim_eligible)throw new Error('请先核对可用的本人来源');const payload:any=action.value==='approve'?{content:item.content,kind:item.kind,importance:item.importance}:{};if(action.value==='approve'&&linkClaim.value){if(!value.value.trim())throw new Error('请填写并核对结构化值');payload.approve_claim=true;payload.claim={predicate:predicate.value,value:value.value.trim(),scope:JSON.parse(scope.value),evidence:[source.value.evidence],condition_evidence:Object.keys(JSON.parse(scope.value)).length?[source.value.evidence]:[],reason:'用户在候选审核中核对原话及结构化字段后明确批准'}}await props.api.request('/memory-reviews/'+encodeURIComponent(item.id)+'/'+action.value,payload);confirm.value=false;selected.value=null;source.value=null;await load();emit('changed')}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}finally{if(alive)busy.value=false}}
onMounted(()=>void load());onUnmounted(()=>{alive=false})
</script>
<template><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="explorer-grid"><section class="panel"><div class="section-title"><h2>记忆候选</h2><el-button :loading="busy" @click="load">刷新</el-button></div><el-select v-model="status" @change="load" aria-label="候选状态"><el-option value="pending" label="待审核"/><el-option value="approved" label="已批准"/><el-option value="rejected" label="已拒绝"/><el-option value="all" label="全部记录"/></el-select><p>最多载入500条。批准前请核对原文与候选含义。</p><button v-for="item in rows" :key="item.id" class="claim-row" :class="{chosen:selected?.id===item.id}" @click="inspect(item)"><div><span>{{ item.kind }}</span><small>{{ item.job_id?.startsWith('manual:')?'手动提出':'自动提取' }}</small><el-tag size="small">{{ item.status }}</el-tag></div><strong>{{ item.content }}</strong><small>{{ dateLabel(item.created_at,true) }}</small></button><div v-if="busy&&!rows.length" class="empty" role="status">正在读取候选…</div><div v-else-if="!rows.length" class="empty"><h3>没有符合条件的候选</h3><p>公开导入资料不会产生本人候选；日常提问也可能没有长期事实。你可以从有效本人原话提出候选。</p><el-button @click="emit('open','conversations')">从历史原话提出</el-button><el-button @click="emit('open','pipeline')">查看提取任务与原因</el-button></div></section><section class="panel"><template v-if="selected"><div class="section-title"><h2>核对与处理</h2><el-tag>{{ selected.status }}</el-tag></div><el-input v-model="selected.content" type="textarea" :rows="4" maxlength="4000" :disabled="selected.status!=='pending'"/><h3>对应原始来源</h3><div v-if="source" class="source-original">{{ source.content }}</div><p v-else>读取来源中，或来源已不可用。</p><el-alert v-if="source&&!source.personal_claim_eligible" title="该原话不能作为本人记忆依据，不能从此界面批准。" type="warning" :closable="false"/><div v-if="selected.status==='pending'"><el-checkbox v-model="linkClaim">同时核对并批准结构化状态，供当前状态查询使用</el-checkbox><div v-if="linkClaim" class="form-grid"><label>属性<el-select v-model="predicate"><el-option v-for="slot in slots" :key="slot" :value="slot" :label="slot"/></el-select></label><label>原话明确支持的值<el-input v-model="value" maxlength="500"/></label><label>适用条件 JSON（默认 {}）<el-input v-model="scope" maxlength="2000"/></label><p>此入口为本人正向陈述、未知事实时间；复杂否定/时序请使用结构化记忆审核。一次确认将原子批准记忆与Claim，冲突或证据错误时全部回滚。</p></div></div><div v-if="selected.status==='pending'" class="actions"><el-button type="primary" :disabled="busy||!source?.personal_claim_eligible" @click="propose('approve')">核对后写入长期记忆</el-button><el-button :disabled="busy" @click="propose('reject')">拒绝候选</el-button></div><p>批准会写入记忆并建立索引，可能调用已配置的Embedding服务；只有勾选并核对完整结构化字段，才联动批准Claim。</p></template><div v-else class="empty"><h3>选择一个候选查看原话</h3><p>候选文本与原始证据并排核对，审核决定由你明确执行。</p></div></section></div><el-dialog v-model="confirm" :title="action==='approve'?'确认写入长期记忆':'确认拒绝候选'" width="440px"><p>{{ selected?.content }}</p><p v-if="action==='approve'&&linkClaim">同时批准：{{ predicate }} = {{ value }}；条件 {{ scope }}；主体本人、正向陈述、事实时间未知。</p><el-checkbox v-model="checked">我已核对原话，确认执行此操作</el-checkbox><template #footer><el-button @click="confirm=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!checked" @click="apply">确认处理</el-button></template></el-dialog></template>
